def count_substring(s, sub):
    count = 0
    for i in range(len(s) - len(sub) + 1):
        if s[i:i + len(sub)] == sub:
            count += 1
    return count

def rotate_list(lst, k):
    if not lst:
        return []
    k = k % len(lst)
    return lst[-k:] + lst[:-k]

def interleave(a, b):
    out = []
    for x, y in zip(a, b):
        out.append(x)
        out.append(y)
    return out

def last_index(lst, x):
    result = -1
    for i, v in enumerate(lst):
        if v == x:
            result = i
    return result

def safe_get(lst, i, default=None):
    if 0 <= i < len(lst):
        return lst[i]
    return default

def drop_while(lst, pred):
    for i, v in enumerate(lst):
        if not pred(v):
            return lst[i:]
    return []

def first_negative(nums):
