def chunk_list(lst, size, fillvalue=None):
    res = []
    for i in range(0, len(lst), size):
        chunk = lst[i:i + size]
        if len(chunk) < size and fillvalue is not None:
            chunk = chunk + [fillvalue] * (size - len(chunk))
        res.append(chunk)
    return res
```

